def _refill(self):
    t = self._now()
    # Only refill if we've recorded a previous time (None is allowed and 0 is valid).
    if self._last is not None:
        self._tokens += (t - self._last) * self.rate
        # Do not exceed capacity when refilling.
        if self._tokens > self.capacity:
            self._tokens = float(self.capacity)
    self._last = t
